func TestFixseneca(t *testing.T) {
	x := `"Perseus:abo:phi,1014,001:Ira. 3:18:3"`
	y := fixseneca(x)
	z := `"Perseus:abo:phi,1017,012:3:3:18:3"`
	fmt.Println(y)
	if y != z {
		t.Errorf("fixseneca(%q)\ngot\n%q\nwant\n%q", x, y, z)
	}
	x = `"Perseus:abo:phi,1014,001:Q. N. 5:16:5"`
	y = fixseneca(x)
	fmt.Println(y)
}

