func TestReformatXML(t *testing.T) {
	//	x := `<bibl n="Perseus:abo:tlg,0012,002:8:556"><title>Od.</title> 8.556</bibl>, cf. <bibl n="Perseus:abo:tlg,0085,001:136"><author>A.</author> <title>Supp.</title> 136</bibl> (lyr.); <cit><quote lang="greek">κραιπνοφόροι δέ μʼ ἔπεμψαν αὖραι</quote> <bibl n="Perseus:abo:tlg,0085,003:132"><author>Id.</author> <title>Pr.</title> 132</bibl></cit> (lyr.), cf. <bibl n="Perseus:abo:tlg,0033,002:4:203"><author>Pi.</author> <title>P.</title> 4.203</bibl> (<gramGrp opt="n"><gram type="voice" opt="n">Pass.</gram></gramGrp>). </sense><sense n="2" id="n80557.10" level="3" opt="n"> <foreign lang="greek">πομπὴν π</foreign>. <i>conduct,</i> or <i>take part in,</i> a procession, <bibl n="Perseus:abo:tlg,0016,001:5:56"><author>Hdt.</author> 5.56</bibl>, <bibl n="Perseus:abo:tlg,0019,010:757"><author>Ar.</author> <title>Ec.</title> 757</bibl>, <bibl n="Perseus:abo:tlg,0003,001:6:56"><author>Th.</author> 6.56</bibl>, <bibl n="Perseus:abo:tlg,0540,013:80"><author>Lys.</author> 13.80</bibl>, <bibl n="Perseus:abo:tlg,0014,004:26"><author>D.</author> 4.26</bibl>, etc.; <foreign lang="greek">π. χορούς</foreign> <i>move in</i> dancing <i>procession,</i> <bibl n="Perseus:abo:tlg,0006,012:434"><author>E.</author> <title>El.</title> 434</bibl> (lyr.); <foreign lang="greek">Παναθήναια π</foreign>. <bibl n="Perseus:abo:tlg,0541,001:494" default="NO"><author>Men.</author> 494</bibl>, <bibl n="Perseus:abo:tlg,0638,001:4:22" default="NO"><author>Philostr.</author> <title>VA</title> 4.22</bibl> :—<gramGrp opt="n"><gram type="voice" opt="n">Pass.</gram></gramGrp>, <foreign lang="greek">φαλλὸς Διονύσῳ πεμπόμενος</foreign> <i>carried in procession</i> in his honour, <bibl n="Perseus:abo:tlg,0016,001:2:49"><author>Hdt.</author> 2.49</bibl>, cf. <bibl n="Perseus:abo:tlg,0007,019:32" default="NO"><author>Plu.</author> <title>Aem.</title> 32</bibl>, <bibl n="Perseus:abo:tlg,0007,057:12" default="NO"><title>Demetr.</title> 12</bibl>; <cit><quote lang="greek">τῆς πομπῆς ὅπως ἂν ὡς κάλλισταπεμφθῇ</quote> <title>IG</title> 1(2).84.27</cit>; <cit><quote lang="greek">χορὸς ὁ εἰς Δῆλον πεμπόμενος</quote> <bibl n="Perseus:abo:tlg,0032,002:3:3:12"><author>X.</author> <title>Mem.</title> 3.3.12</bibl></cit>. </sense><sense n="IV" id="n80557.11" level="2" opt="n"> <i>send</i> as a present, <foreign lang="greek">εἵματα, σῖτον,</foreign> <bibl n="Perseus:abo:tlg,0012,002:16:83"><title>Od.</title> 16.83</bibl>, <bibl n="Perseus:abo:tlg,0012,002:4:623">4.623</bibl>; <foreign lang="greek">π. δῶρα, σκῦλα, ξένια,</foreign> <bibl n="Perseus:abo:tlg,0016,001:7:106"><author>Hdt.</author> 7.106</bibl> (<gramGrp opt="n"><gram type="voice" opt="n">Act.</gram></gramGrp> and <gramGrp opt="n"><gram type="voice" opt="n">Pass.</gram></gramGrp>), <bibl n="Perseus:abo:tlg,0011,006:1429"><author>S.</author> <title>Ph.</title> 1429</bibl>, <bibl n="Perseus:abo:tlg,0032,007:3:1:42"><author>X.</author> <title>Cyr.</title> 3.1.42</bibl>. </sense><sense n="V" id="n80557.12" level="2" opt="n"> <i>send up, produce,</i> <cit><quote lang="greek">ὅσα πέμπει βιόδωρος αἶα</quote> <bibl n="Perseus:abo:tlg,0011,006:1162"><author>S.</author> <title>Ph.</title> 1162</bibl></cit> (lyr.). </sense><sense n="B" id="n80557.13" level="1" opt="n"> <gramGrp opt="n"><gram type="voice" opt="n">Med.</gram></gramGrp>, <foreign lang="greek">πέμπεσθαί τινα</foreign> <i>send for</i> one, <bibl n="Perseus:abo:tlg,0011,007:602"><author>S.</author> <title>OC</title> 602</bibl>, ubiv. Sch.; <foreign lang="greek">τί χρῆμʼ ἐπέμψω τὸν ἐμὸν ἐκ δόμων πόδα</foreign>; <bibl n="Perseus:abo:tlg,0006,007:977"><author>E.</author> <title>Hec.</title> 977</bibl>. </sense><sense n="II" id="n80557.14" level="2" opt="n"> <i>send in oneʼs own service</i> or <i>cause to be sent,</i> <bibl n="Perseus:abo:tlg,0011,004:556"><author>S.</author> <title>OT</title> 556</bibl>, <bibl n="Perseus:abo:tlg,0062,044:14" default="NO"><author>Luc.</author> <title>Tox.</title> 14</bibl>.`
	x := `<div2 id="crosspe/mpw" orig_id="n80557" key="pe/mpw" type="main" opt="n"><head extent="full" lang="greek" opt="n" orth_orig="πέμπω">πέμπω</head>, <gramGrp opt="n"><gram type="dialect" opt="n">Ep.</gram></gramGrp> <mood opt="n">inf.</mood> <foreign lang="greek">-έμεναι, -έμεν,</foreign> <bibl n="Perseus:abo:tlg,0012,002:13:48"><title>Od.</title> 13.48</bibl>, <bibl n="Perseus:abo:tlg,0012,002:10:18">10.18</bibl> : <gramGrp opt="n"><gram type="dialect" opt="n">Ion.</gram></gramGrp> <tns opt="n">impf.</tns> <cit><quote lang="greek">πέμπεσκε</quote> <bibl n="Perseus:abo:tlg,0016,001:7:106"><author>Hdt.</author> 7.106</bibl></cit> : <tns opt="n">fut.</tns> <cit><quote lang="greek">πέμψω</quote> <bibl n="Perseus:abo:tlg,0012,002:5:167"><title>Od.</title> 5.167</bibl></cit>, etc.; <gramGrp opt="n"><gram type="dialect" opt="n">Dor.</gram></gramGrp> <cit><quote lang="greek">πεμψῶ</quote> <bibl n="Perseus:abo:tlg,0005,001:5:141"><author>Theoc.</author> 5.141</bibl></cit>; <gramGrp opt="n"><gram type="dialect" opt="n">Ep.</gram></gramGrp> <mood opt="n">inf.</mood> <cit><quote lang="greek">πεμψέμεναι</quote> <bibl n="Perseus:abo:tlg,0012,002:10:484"><title>Od.</title> 10.484</bibl></cit>: <tns opt="n">aor.</tns> <foreign lang="greek">ἔπεμψα,</foreign> <gramGrp opt="n"><gram type="dialect" opt="n">Ep.</gram></gramGrp> <cit><quote lang="greek">πέμψα</quote> <bibl n="Perseus:abo:tlg,0012,001:1:442"><title>Il.</title> 1.442</bibl></cit>, <bibl n="Perseus:abo:tlg,0012,001:21:43">21.43</bibl>, etc.: <tns opt="n">pf.</tns> <cit><quote lang="greek">πέπομφα</quote> <bibl n="Perseus:abo:tlg,0003,001:7:12"><author>Th.</author> 7.12</bibl></cit>, <bibl n="Perseus:abo:tlg,0032,007:6:2:10"><author>X.</author> <title>Cyr.</title> 6.2.10</bibl>, <bibl n="Perseus:abo:tlg,0014,004:48"><author>D.</author> 4.48</bibl> : <tns opt="n">plpf.</tns> <foreign lang="greek">ἐπεμπόμφει,</foreign> <gramGrp opt="n"><gram type="dialect" opt="n">Ion.</gram></gramGrp> <foreign lang="greek">-εε,</foreign> <bibl n="Perseus:abo:tlg,0032,007:6:2:9"><author>X.</author> <title>Cyr.</title> 6.2.9</bibl>, <bibl n="Perseus:abo:tlg,0016,001:1:85"><author>Hdt.</author> 1.85</bibl> :—<gramGrp opt="n"><gram type="voice" opt="n">Med.</gram></gramGrp> (not in early Prose, exc. in compds. <foreign lang="greek">ἀπο-, μετα-, προ-πέμπομαι</foreign>), <tns opt="n">fut.</tns> <foreign lang="greek">πέμψομαι</foreign> only <abbr>f.l.</abbr> in <bibl n="Perseus:abo:tlg,0006,016:111"><author>E.</author> <title>Or.</title> 111</bibl> : <tns opt="n">aor.</tns> <cit><quote lang="greek">ἐπεμψάμην</quote> <bibl n="Perseus:abo:tlg,0006,007:977"><author>Id.</author> <title>Hec.</title> 977</bibl></cit> :—<gramGrp opt="n"><gram type="voice" opt="n">Pass.</gram></gramGrp>, <tns opt="n">fut.</tns> <cit><quote lang="greek">πεμφθήσομαι</quote> <bibl n="Perseus:abo:tlg,0099,001:1:1:4"><author>Str.</author> 1.1.4</bibl></cit>, <bibl n="Perseus:abo:tlg,0007,057:27" default="NO"><author>Plu.</author> <title>Demetr.</title> 27</bibl> : <tns opt="n">aor.</tns> <cit><quote lang="greek">ἐπέμφθην</quote> <bibl n="Perseus:abo:tlg,0033,003:3:59"><author>Pi.</author> <title>N.</title> 3.59</bibl></cit>, <bibl n="Perseus:abo:tlg,0011,005:1163"><author>S.</author> <title>El.</title> 1163</bibl>, etc.: <per opt="n">3</per> <number opt="n">sg.</number> <tns opt="n">pf.</tns> <cit><quote lang="greek">πέπεμπται</quote> <bibl n="Perseus:abo:tlg,0085,004:473"><author>A.</author> <title>Th.</title> 473</bibl></cit>, (<etym lang="greek" opt="n">προ-</etym>) <bibl n="Perseus:abo:tlg,0003,001:7:77"><author>Th.</author> 7.77</bibl>; <mood opt="n">part.</mood> <cit><quote lang="greek">πεπεμμένος</quote> <bibl n="Perseus:abo:tlg,0014,023:159"><author>D.</author> 23.159</bibl></cit>, <bibl n="Perseus:abo:tlg,0062,038:32" default="NO"><author>Luc.</author> <title>Alex.</title> 32</bibl>, <bibl n="Perseus:abo:tlg,0385,001:50:13" default="NO"><author>D.C.</author> 50.13</bibl>: <tns opt="n">plpf.</tns> <cit><quote lang="greek">ἐπέπεμπτο</quote> <bibl n="Perseus:abo:tlg,0385,001:36:18" default="NO"><author>Id.</author> 36.18</bibl></cit>, (<etym lang="greek" opt="n">προὐπ-</etym>) <bibl n="Perseus:abo:tlg,0003,001:8:79"><author>Th.</author> 8.79</bibl> (cj.) :—<sense id="n80557.0" n="" level="1" opt="n"><i>send,</i> freq. of persons, as messengers, spies, etc., <bibl n="Perseus:abo:tlg,0012,001:3:116"><title>Il.</title> 3.116</bibl>, <bibl n="Perseus:abo:tlg,0085,004:37"><author>A.</author> <title>Th.</title> 37</bibl>, <bibl n="Perseus:abo:tlg,0016,001:7:15"><author>Hdt.</author> 7.15</bibl>, etc.; of troops, <bibl n="Perseus:abo:tlg,0085,002:34"><author>A.</author> <title>Pers.</title> 34</bibl> (anap.), <bibl n="Perseus:abo:tlg,0085,004:470"><title>Th.</title> 470</bibl> : c. dupl. acc., <foreign lang="greek">ὁδὸν π. τινά</foreign> <i>send</i> one <i>on</i> a journey, <bibl n="Perseus:abo:tlg,0011,003:739"><author>S.</author> <title>Aj.</title> 739</bibl>, cf. <bibl n="Perseus:abo:tlg,0011,005:1163"><title>El.</title> 1163</bibl> (<gramGrp opt="n"><gram type="voice" opt="n">Pass.</gram></gramGrp>); also of things, <cit><quote lang="greek">πέμψω δέ τοι οὖρον ὄπισθεν</quote> <bibl n="Perseus:abo:tlg,0012,002:5:167"><title>Od.</title> 5.167</bibl></cit>, etc.; <foreign lang="greek">π. γράμματα, ἐπιστολήν,</foreign> <bibl n="Perseus:abo:tlg,0059,036:310d"><author>Pl.</author> <title>Ep.</title> 310d</bibl>, <bibl n="Perseus:abo:tlg,0059,036:323b">323b</bibl>; in letters, in the epistolary aorist, <bibl n="Perseus:abo:tlg,0003,001:1:129"><author>Th.</author> 1.129</bibl>, <bibl n="Perseus:abo:tlg,0032,006:1:9:25"><author>X.</author> <title>An.</title> 1.9.25</bibl>, <bibl n="Perseus:abo:tlg,0527,018:4:14"><author>LXX</author> <title>2 Es.</title> 4.14</bibl>; <foreign lang="greek">π. κακόν τινι</foreign> <i>send</i> one evil, <bibl n="Perseus:abo:tlg,0012,001:15:109"><title>Il.</title> 15.109</bibl>; <cit><quote lang="greek">π. παραβᾶσιν Ἐρινύν</quote> <bibl n="Perseus:abo:tlg,0085,005:59"><author>A.</author> <title>Ag.</title> 59</bibl></cit> (anap.); <foreign lang="greek">ποινάς, ζημίαν,</foreign> <bibl n="Perseus:abo:tlg,0085,007:203"><author>Id.</author> <title>Eu.</title> 203</bibl> (dub.), <bibl n="Perseus:abo:tlg,0006,020:506" default="NO"><author>E.</author> <title>Fr.</title> 506</bibl>; <cit><quote lang="greek">ψόφον π. ἔσω</quote> <bibl n="Perseus:abo:tlg,0006,013:1308"><author>Id.</author> <title>IT</title> 1308</bibl></cit>; <foreign lang="greek">ὕπνον, ὀνείρατα,</foreign> <bibl n="Perseus:abo:tlg,0011,006:19"><author>S.</author> <title>Ph.</title> 19</bibl>, <bibl n="Perseus:abo:tlg,0011,005:460"><title>El.</title> 460</bibl>; freq. of omens, <foreign lang="greek">π. οἰωνόν, τέρατα,</foreign> <bibl n="Perseus:abo:tlg,0012,001:24:310"><title>Il.</title> 24.310</bibl>, <bibl n="Perseus:abo:tlg,0032,002:1:4:15"><author>X.</author> <title>Mem.</title> 1.4.15</bibl>, cf. <bibl n="Perseus:abo:tlg,0032,004:4:48"><title>Smp.</title> 4.48</bibl>; <cit><quote lang="greek">μαντείας</quote> <bibl n="Perseus:abo:tlg,0011,004:149"><author>S.</author> <title>OT</title> 149</bibl></cit>; also <cit><quote lang="greek">ἱκεσίους π. λιτάς</quote> <bibl n="Perseus:abo:tlg,0011,006:495"><author>Id.</author> <title>Ph.</title> 495</bibl></cit> ; <foreign lang="greek">π. ἀρωγάς, ἀλκάν,</foreign> <bibl n="Perseus:abo:tlg,0085,007:598"><author>A.</author> <title>Eu.</title> 598</bibl>, <bibl n="Perseus:abo:tlg,0011,004:189"><author>S.</author> <title>OT</title> 189</bibl> (lyr.) :—Constr.: </sense><sense n="1" id="n80557.1" level="3" opt="n"> c. acc. of place to which, <foreign lang="greek">π. τινὰ Θήβας, ἀγρούς,</foreign> <bibl n="Perseus:abo:tlg,0011,007:1770"><author>Id.</author> <title>OC</title> 1770</bibl> (anap.), <bibl n="Perseus:abo:tlg,0011,004:761"><title>OT</title> 761</bibl> : also c. dat., <cit><quote lang="greek">Ἀΐδᾳ</quote> <bibl n="Perseus:abo:tlg,0006,013:159"><author>E.</author> <title>IT</title> 159</bibl></cit> (anap.): but usu. with Preps., <foreign lang="greek">ἐς Τροίην, φίλην ἐς πατρίδα γαῖαν,</foreign> etc., <bibl n="Perseus:abo:tlg,0012,001:6:207"><title>Il.</title> 6.207</bibl>, <bibl n="Perseus:abo:tlg,0012,002:5:37"><title>Od.</title> 5.37</bibl>, etc.; <cit><quote lang="greek">π. εἰς Ἀΐδαο</quote> <bibl n="Perseus:abo:tlg,0012,001:21:48"><title>Il.</title> 21.48</bibl></cit> ; <cit><quote lang="greek">δόμον Ἄϊδος εἴσω</quote> <bibl n="Perseus:abo:tlg,0012,002:9:524"><title>Od.</title> 9.524</bibl></cit>; <foreign lang="greek">π. εἰς διδασκάλων</foreign> <i>send</i> to school, <bibl n="Perseus:abo:tlg,0059,022:325d"><author>Pl.</author> <title>Prt.</title> 325d</bibl> (so <foreign lang="greek">πέμπειν</foreign> alone, <bibl n="Perseus:abo:tlg,0019,012:216" default="NO"><author>Ar.</author> <title>Fr.</title> 216</bibl>); <foreign lang="greek">π. ἐπʼ εὐρέα νῶτα θαλάσσης</foreign> <i>over. . ,</i> <bibl n="Perseus:abo:tlg,0012,002:4:560"><title>Od.</title> 4.560</bibl>, etc. ; <foreign lang="greek">π.ἐπὶ Θρῃκῶν ἵππους</foreign> <i>to</i> them, <bibl n="Perseus:abo:tlg,0012,001:10:464"><title>Il.</title> 10.464</bibl>; but <foreign lang="greek">πέμπειν ἐπί τι</foreign> <i>send for</i> a purpose, <cit><quote lang="greek">ἐπʼ ὕδωρ</quote> <bibl n="Perseus:abo:tlg,0016,001:5:12"><author>Hdt.</author> 5.12</bibl></cit> ; <cit><quote lang="greek">ἐπὶ κατασκοπήν</quote> <bibl n="Perseus:abo:tlg,0032,007:6:2:9"><author>X.</author> <title>Cyr.</title> 6.2.9</bibl></cit> (<foreign lang="greek">π. εἰς κ</foreign>. <bibl n="Perseus:abo:tlg,0011,006:45"><author>S.</author> <title>Ph.</title> 45</bibl>); <cit><quote lang="greek">π. ἀρωγὴν ἐπὶ νίκην</quote> <bibl n="Perseus:abo:tlg,0085,006:477"><author>A.</author> <title>Ch.</title> 477</bibl></cit> codd. (anap.); <foreign lang="greek">π. ἐπί τινι</foreign> <i>send to</i> him, <bibl n="Perseus:abo:tlg,0012,001:2:6"><title>Il.</title> 2.6</bibl>; <i>against. . ,</i> <bibl n="Perseus:abo:tlg,0085,005:61"><author>A.</author> <title>Ag.</title> 61</bibl> (anap.), etc.; <i>for</i> a purpose, <cit><quote lang="greek">ἐπὶ πολέμῳ</quote> <bibl n="Perseus:abo:tlg,0032,001:4:8:17"><author>X.</author> <title>HG</title> 4.8.17</bibl></cit>; <foreign lang="greek">περί τινος</foreign> about something, <bibl n="Perseus:abo:tlg,0003,001:1:91"><author>Th.</author> 1.91</bibl>, <bibl n="Perseus:abo:tlg,0032,007:6:2:10"><author>X.</author> <title>Cyr.</title> 6.2.10</bibl>; <foreign lang="greek">ὑπέρ τινος</foreign> Epist. Philipp. ap. <bibl n="Perseus:abo:tlg,0014,012:12"><author>D.</author> 12.12</bibl>; <foreign lang="greek">παρά</foreign> or <foreign lang="greek">πρός τινα</foreign> <i>to</i> some one, <bibl n="Perseus:abo:tlg,0003,001:2:81"><author>Th.</author> 2.81</bibl>, <bibl n="Perseus:abo:tlg,0032,006:5:2:6"><author>X.</author> <title>An.</title> 5.2.6</bibl>; <cit><quote lang="greek">ὥς τινα</quote> <bibl n="Perseus:abo:tlg,0003,001:8:50"><author>Th.</author> 8.50</bibl></cit>. </sense><sense n="2" id="n80557.2" level="3" opt="n"> folld. by Advbs., <foreign lang="greek">οἴκαδε, οἶκόνδε,</foreign> <bibl n="Perseus:abo:tlg,0012,002:19:281"><title>Od.</title> 19.281</bibl>, <bibl n="Perseus:abo:tlg,0012,002:24:418">24.418</bibl>; <cit><quote lang="greek">ὅνδε δόμονδε</quote> <bibl n="Perseus:abo:tlg,0012,001:16:445"><title>Il.</title> 16.445</bibl></cit>; <cit><quote lang="greek">θύραζε</quote> <bibl n="Perseus:abo:tlg,0012,002:9:461"><title>Od.</title> 9.461</bibl></cit>; <cit><quote lang="greek">πόλεμόνδε</quote> <bibl n="Perseus:abo:tlg,0012,001:18:452"><title>Il.</title> 18.452</bibl></cit>, etc.; <foreign lang="greek">ἕταρον γὰρ . . πέμπʼ Ἄϊδόσδε</foreign> <i>was conducting</i> or <i>convoying</i> Patroclus to Hades, <bibl n="Perseus:abo:tlg,0012,001:23:137">23.137</bibl>. </sense><sense n="3" id="n80557.3" level="3" opt="n"> folld. by <mood opt="n">inf.</mood> of purpose, <cit><quote lang="greek">τὴν . . ἅρμασι π. νέεσθαι</quote> <bibl n="Perseus:abo:tlg,0012,002:4:8"><title>Od.</title> 4.8</bibl></cit> ; <cit><quote lang="greek">ἕπεσθαι</quote> <bibl n="Perseus:abo:tlg,0012,001:16:575"><title>Il.</title> 16.575</bibl></cit> ; <cit><quote lang="greek">ἰέναι</quote> <bibl n="Perseus:abo:tlg,0012,002:14:396"><title>Od.</title> 14.396</bibl></cit> ; <cit><quote lang="greek">ἱκανέμεν</quote> <bibl n="Perseus:abo:tlg,0012,002:4:29">4.29</bibl></cit> ; <cit><quote lang="greek">ἄγειν</quote> <bibl n="Perseus:abo:tlg,0012,002:24:419">24.419</bibl></cit>; <cit><quote lang="greek">φέρειν</quote> <bibl n="Perseus:abo:tlg,0012,001:16:454"><title>Il.</title> 16.454</bibl></cit> ; <foreign lang="greek">φέρεσθαι</foreign> ib. <bibl n="Perseus:abo:tlg,0012,001:16:681">681</bibl> ; <cit><quote lang="greek">μήτηρ με πέμπει πατρὶ τυμβεῦσαι χοάς</quote> <bibl n="Perseus:abo:tlg,0011,005:406"><author>S.</author> <title>El.</title> 406</bibl></cit> ; <i>send word,</i> <cit><quote lang="greek">πέμπεις . . σῇ δάμαρτι, παῖδα σὴν δεῦρʼ ἀποστέλλειν</quote> <bibl n="Perseus:abo:tlg,0006,018:360"><author>E.</author> <title>IA</title> 360</bibl></cit> ; <foreign lang="greek">πέμπουσιν οἱ ἔφοροι . . στρατεύεσθαι</foreign> <i>sent him orders</i> to march, <bibl n="Perseus:abo:tlg,0032,001:3:1:7"><author>X.</author> <title>HG</title> 3.1.7</bibl> : also c. <mood opt="n">part.</mood>, <cit><quote lang="greek">κήρυκας π. ἀγγέλλοντας</quote> <title>IG</title> 1(2).76.22</cit> : the place from which is expressed by <foreign lang="greek">ἀπό</foreign> or <foreign lang="greek">ἐκ,</foreign> <bibl n="Perseus:abo:tlg,0012,001:16:447"><title>Il.</title> 16.447</bibl>, <bibl n="Perseus:abo:tlg,0012,002:11:635"><title>Od.</title> 11.635</bibl>, etc. </sense><sense n="4" id="n80557.4" level="3" opt="n"> abs., <cit><quote lang="greek">ἐπέμψαμεν πρὸς ὑμᾶς περὶ ἀποστάσεως</quote> <bibl n="Perseus:abo:tlg,0003,001:3:13"><author>Th.</author> 3.13</bibl></cit> ; <cit><quote lang="greek">πέμπει κελεύων</quote> <bibl n="Perseus:abo:tlg,0003,001:1:91"><author>Th.</author> 1.91</bibl></cit>, <bibl n="Perseus:abo:tlg,0003,001:2:81">2.81</bibl>; <cit><quote lang="greek">ἐκέλευε . . πέμπων</quote> <bibl n="Perseus:abo:tlg,0032,006:2:3:1"><author>X.</author> <title>An.</title> 2.3.1</bibl></cit> ; <cit><quote lang="greek">ἔπεμπε πρὸς Κῦρον δεόμενος</quote> <bibl n="Perseus:abo:tlg,0032,007:1:5:4"><author>Id.</author> <title>Cyr.</title> 1.5.4</bibl></cit> ; <cit><quote lang="greek">ἔπεμπον ἐρωτῶντες</quote> <bibl n="Perseus:abo:tlg,0032,006:6:6:4"><author>Id.</author> <title>An.</title> 6.6.4</bibl></cit>, etc. </sense><sense n="5" id="n80557.5" level="3" opt="n"> <i>send forward, nominate</i> a person for a post, <foreign lang="greek">ὀνόματα</foreign> Wilcken <title>Chr.</title> 28.20 <date>(ii A.D.)</date> :—<gramGrp opt="n"><gram type="voice" opt="n">Pass.</gram></gramGrp>, ib. 392.7 <date>(ii A.D.)</date>. </sense><sense n="II" id="n80557.6" level="2" opt="n"> <i>send forth</i> or <i>away, dismiss, send home,</i> <cit><quote lang="greek">τὸν ξεῖνον</quote> <bibl n="Perseus:abo:tlg,0012,002:7:227"><title>Od.</title> 7.227</bibl></cit>, al.: less freq. in <title>Il.</title>, as <bibl n="Perseus:abo:tlg,0012,001:24:780">24.780</bibl>; <foreign lang="greek">χρὴ ξεῖνον παρεόντα φιλεῖν, ἐθέλοντα δὲ πέμπειν</foreign> ‘welcome the coming, <i>speed</i> the parting guest’, <bibl n="Perseus:abo:tlg,0012,002:15:74"><title>Od.</title> 15.74</bibl> ; <cit><quote lang="greek">ὑπέδεκτο καὶ πέμπε</quote> <bibl n="Perseus:abo:tlg,0012,002:23:315">23.315</bibl></cit> ; of the father who sends off his daughter to go to her husband, c. dat., <bibl n="Perseus:abo:tlg,0012,002:4:5">4.5</bibl> ; <cit><quote lang="greek">π. τινὰ ἄποικον</quote> <bibl n="Perseus:abo:tlg,0011,004:1518"><author>S.</author> <title>OT</title> 1518</bibl></cit>, etc. </sense><sense n="2" id="n80557.7" level="3" opt="n"> of missiles, <i>discharge, shoot,</i> <cit><quote lang="greek">πέτρας</quote> <bibl n="Perseus:abo:tlg,0020,001:716"><author>Hes.</author> <title>Th.</title> 716</bibl></cit> : metaph., <cit><quote lang="greek">ὄμματος . . τόξευμα</quote> <bibl n="Perseus:abo:tlg,0085,001:1005"><author>A.</author> <title>Supp.</title> 1005</bibl></cit> : abs., <cit><quote lang="greek">οἱ πολλάκις πέμποντες ἔστιν ὅτε τυγχάνουσι τοῦ σκοποῦ</quote> <bibl n="Perseus:abo:tlg,2050,001:p.495" default="NO"><author>Eun.</author> <title>VS</title> p.495</bibl></cit> B. </sense><sense n="3" id="n80557.8" level="3" opt="n"> of words, <i>send forth, utter,</i> <bibl n="Perseus:abo:tlg,0085,004:443"><author>A.</author> <title>Th.</title> 443</bibl>, <bibl n="Perseus:abo:tlg,0011,006:846"><author>S.</author> <title>Ph.</title> 846</bibl> (lyr.), <bibl n="Perseus:abo:tlg,0011,006:1445">1445</bibl> (anap.). </sense><sense n="III" id="n80557.9" level="2" opt="n"> <i>conduct, escort,</i> <bibl n="Perseus:abo:tlg,0012,001:1:390"><title>Il.</title> 1.390</bibl>, <bibl n="Perseus:abo:tlg,0012,002:14:336"><title>Od.</title> 14.336</bibl>, <bibl n="Perseus:abo:tlg,0011,001:571"><author>S.</author> <title>Tr.</title> 571</bibl>, etc.; freq. of Hermes and other gods, <bibl n="Perseus:abo:tlg,0012,002:11:626"><title>Od.</title> 11.626</bibl>, <bibl n="Perseus:abo:tlg,0085,007:12"><author>A.</author> <title>Eu.</title> 12</bibl>, <bibl n="Perseus:abo:tlg,0085,001:219"><title>Supp.</title> 219</bibl>; <foreign lang="greek">ὁ πέμπων</foreign> abs., of Hermes, <bibl n="Perseus:abo:tlg,0011,006:133"><author>S.</author> <title>Ph.</title> 133</bibl> (cf. <foreign lang="greek">πομπός, πομπαῖος,</foreign> etc.); of a ship, <i>convey, carry,</i> <bibl n="Perseus:abo:tlg,0012,002:8:556"><title>Od.</title> 8.556</bibl>, cf. <bibl n="Perseus:abo:tlg,0085,001:136"><author>A.</author> <title>Supp.</title> 136</bibl> (lyr.); <cit><quote lang="greek">κραιπνοφόροι δέ μʼ ἔπεμψαν αὖραι</quote> <bibl n="Perseus:abo:tlg,0085,003:132"><author>Id.</author> <title>Pr.</title> 132</bibl></cit> (lyr.), cf. <bibl n="Perseus:abo:tlg,0033,002:4:203"><author>Pi.</author> <title>P.</title> 4.203</bibl> (<gramGrp opt="n"><gram type="voice" opt="n">Pass.</gram></gramGrp>). </sense><sense n="2" id="n80557.10" level="3" opt="n"> <foreign lang="greek">πομπὴν π</foreign>. <i>conduct,</i> or <i>take part in,</i> a procession, <bibl n="Perseus:abo:tlg,0016,001:5:56"><author>Hdt.</author> 5.56</bibl>, <bibl n="Perseus:abo:tlg,0019,010:757"><author>Ar.</author> <title>Ec.</title> 757</bibl>, <bibl n="Perseus:abo:tlg,0003,001:6:56"><author>Th.</author> 6.56</bibl>, <bibl n="Perseus:abo:tlg,0540,013:80"><author>Lys.</author> 13.80</bibl>, <bibl n="Perseus:abo:tlg,0014,004:26"><author>D.</author> 4.26</bibl>, etc.; <foreign lang="greek">π. χορούς</foreign> <i>move in</i> dancing <i>procession,</i> <bibl n="Perseus:abo:tlg,0006,012:434"><author>E.</author> <title>El.</title> 434</bibl> (lyr.); <foreign lang="greek">Παναθήναια π</foreign>. <bibl n="Perseus:abo:tlg,0541,001:494" default="NO"><author>Men.</author> 494</bibl>, <bibl n="Perseus:abo:tlg,0638,001:4:22" default="NO"><author>Philostr.</author> <title>VA</title> 4.22</bibl> :—<gramGrp opt="n"><gram type="voice" opt="n">Pass.</gram></gramGrp>, <foreign lang="greek">φαλλὸς Διονύσῳ πεμπόμενος</foreign> <i>carried in procession</i> in his honour, <bibl n="Perseus:abo:tlg,0016,001:2:49"><author>Hdt.</author> 2.49</bibl>, cf. <bibl n="Perseus:abo:tlg,0007,019:32" default="NO"><author>Plu.</author> <title>Aem.</title> 32</bibl>, <bibl n="Perseus:abo:tlg,0007,057:12" default="NO"><title>Demetr.</title> 12</bibl>; <cit><quote lang="greek">τῆς πομπῆς ὅπως ἂν ὡς κάλλισταπεμφθῇ</quote> <title>IG</title> 1(2).84.27</cit>; <cit><quote lang="greek">χορὸς ὁ εἰς Δῆλον πεμπόμενος</quote> <bibl n="Perseus:abo:tlg,0032,002:3:3:12"><author>X.</author> <title>Mem.</title> 3.3.12</bibl></cit>. </sense><sense n="IV" id="n80557.11" level="2" opt="n"> <i>send</i> as a present, <foreign lang="greek">εἵματα, σῖτον,</foreign> <bibl n="Perseus:abo:tlg,0012,002:16:83"><title>Od.</title> 16.83</bibl>, <bibl n="Perseus:abo:tlg,0012,002:4:623">4.623</bibl>; <foreign lang="greek">π. δῶρα, σκῦλα, ξένια,</foreign> <bibl n="Perseus:abo:tlg,0016,001:7:106"><author>Hdt.</author> 7.106</bibl> (<gramGrp opt="n"><gram type="voice" opt="n">Act.</gram></gramGrp> and <gramGrp opt="n"><gram type="voice" opt="n">Pass.</gram></gramGrp>), <bibl n="Perseus:abo:tlg,0011,006:1429"><author>S.</author> <title>Ph.</title> 1429</bibl>, <bibl n="Perseus:abo:tlg,0032,007:3:1:42"><author>X.</author> <title>Cyr.</title> 3.1.42</bibl>. </sense><sense n="V" id="n80557.12" level="2" opt="n"> <i>send up, produce,</i> <cit><quote lang="greek">ὅσα πέμπει βιόδωρος αἶα</quote> <bibl n="Perseus:abo:tlg,0011,006:1162"><author>S.</author> <title>Ph.</title> 1162</bibl></cit> (lyr.). </sense><sense n="B" id="n80557.13" level="1" opt="n"> <gramGrp opt="n"><gram type="voice" opt="n">Med.</gram></gramGrp>, <foreign lang="greek">πέμπεσθαί τινα</foreign> <i>send for</i> one, <bibl n="Perseus:abo:tlg,0011,007:602"><author>S.</author> <title>OC</title> 602</bibl>, ubiv. Sch.; <foreign lang="greek">τί χρῆμʼ ἐπέμψω τὸν ἐμὸν ἐκ δόμων πόδα</foreign>; <bibl n="Perseus:abo:tlg,0006,007:977"><author>E.</author> <title>Hec.</title> 977</bibl>. </sense><sense n="II" id="n80557.14" level="2" opt="n"> <i>send in oneʼs own service</i> or <i>cause to be sent,</i> <bibl n="Perseus:abo:tlg,0011,004:556"><author>S.</author> <title>OT</title> 556</bibl>, <bibl n="Perseus:abo:tlg,0062,044:14" default="NO"><author>Luc.</author> <title>Tox.</title> 14</bibl>.</sense></div2>`
	y := reformatgkxml(x)
	fmt.Println(y)
}

func TestFindGreekLexEntries(t *testing.T) {
	//	x := `<bibl n="Perseus:abo:tlg,0012,002:8:556"><title>Od.</title> 8.556</bibl>, cf. <bibl n="Perseus:abo:tlg,0085,001:136"><author>A.</author> <title>Supp.</title> 136</bibl> (lyr.); <cit><quote lang="greek">κραιπνοφόροι δέ μʼ ἔπεμψαν αὖραι</quote> <bibl n="Perseus:abo:tlg,0085,003:132"><author>Id.</author> <title>Pr.</title> 132</bibl></cit> (lyr.), cf. <bibl n="Perseus:abo:tlg,0033,002:4:203"><author>Pi.</author> <title>P.</title> 4.203</bibl> (<gramGrp opt="n"><gram type="voice" opt="n">Pass.</gram></gramGrp>). </sense><sense n="2" id="n80557.10" level="3" opt="n"> <foreign lang="greek">πομπὴν π</foreign>. <i>conduct,</i> or <i>take part in,</i> a procession, <bibl n="Perseus:abo:tlg,0016,001:5:56"><author>Hdt.</author> 5.56</bibl>, <bibl n="Perseus:abo:tlg,0019,010:757"><author>Ar.</author> <title>Ec.</title> 757</bibl>, <bibl n="Perseus:abo:tlg,0003,001:6:56"><author>Th.</author> 6.56</bibl>, <bibl n="Perseus:abo:tlg,0540,013:80"><author>Lys.</author> 13.80</bibl>, <bibl n="Perseus:abo:tlg,0014,004:26"><author>D.</author> 4.26</bibl>, etc.; <foreign lang="greek">π. χορούς</foreign> <i>move in</i> dancing <i>procession,</i> <bibl n="Perseus:abo:tlg,0006,012:434"><author>E.</author> <title>El.</title> 434</bibl> (lyr.); <foreign lang="greek">Παναθήναια π</foreign>. <bibl n="Perseus:abo:tlg,0541,001:494" default="NO"><author>Men.</author> 494</bibl>, <bibl n="Perseus:abo:tlg,0638,001:4:22" default="NO"><author>Philostr.</author> <title>VA</title> 4.22</bibl> :—<gramGrp opt="n"><gram type="voice" opt="n">Pass.</gram></gramGrp>, <foreign lang="greek">φαλλὸς Διονύσῳ πεμπόμενος</foreign> <i>carried in procession</i> in his honour, <bibl n="Perseus:abo:tlg,0016,001:2:49"><author>Hdt.</author> 2.49</bibl>, cf. <bibl n="Perseus:abo:tlg,0007,019:32" default="NO"><author>Plu.</author> <title>Aem.</title> 32</bibl>, <bibl n="Perseus:abo:tlg,0007,057:12" default="NO"><title>Demetr.</title> 12</bibl>; <cit><quote lang="greek">τῆς πομπῆς ὅπως ἂν ὡς κάλλισταπεμφθῇ</quote> <title>IG</title> 1(2).84.27</cit>; <cit><quote lang="greek">χορὸς ὁ εἰς Δῆλον πεμπόμενος</quote> <bibl n="Perseus:abo:tlg,0032,002:3:3:12"><author>X.</author> <title>Mem.</title> 3.3.12</bibl></cit>. </sense><sense n="IV" id="n80557.11" level="2" opt="n"> <i>send</i> as a present, <foreign lang="greek">εἵματα, σῖτον,</foreign> <bibl n="Perseus:abo:tlg,0012,002:16:83"><title>Od.</title> 16.83</bibl>, <bibl n="Perseus:abo:tlg,0012,002:4:623">4.623</bibl>; <foreign lang="greek">π. δῶρα, σκῦλα, ξένια,</foreign> <bibl n="Perseus:abo:tlg,0016,001:7:106"><author>Hdt.</author> 7.106</bibl> (<gramGrp opt="n"><gram type="voice" opt="n">Act.</gram></gramGrp> and <gramGrp opt="n"><gram type="voice" opt="n">Pass.</gram></gramGrp>), <bibl n="Perseus:abo:tlg,0011,006:1429"><author>S.</author> <title>Ph.</title> 1429</bibl>, <bibl n="Perseus:abo:tlg,0032,007:3:1:42"><author>X.</author> <title>Cyr.</title> 3.1.42</bibl>. </sense><sense n="V" id="n80557.12" level="2" opt="n"> <i>send up, produce,</i> <cit><quote lang="greek">ὅσα πέμπει βιόδωρος αἶα</quote> <bibl n="Perseus:abo:tlg,0011,006:1162"><author>S.</author> <title>Ph.</title> 1162</bibl></cit> (lyr.). </sense><sense n="B" id="n80557.13" level="1" opt="n"> <gramGrp opt="n"><gram type="voice" opt="n">Med.</gram></gramGrp>, <foreign lang="greek">πέμπεσθαί τινα</foreign> <i>send for</i> one, <bibl n="Perseus:abo:tlg,0011,007:602"><author>S.</author> <title>OC</title> 602</bibl>, ubiv. Sch.; <foreign lang="greek">τί χρῆμʼ ἐπέμψω τὸν ἐμὸν ἐκ δόμων πόδα</foreign>; <bibl n="Perseus:abo:tlg,0006,007:977"><author>E.</author> <title>Hec.</title> 977</bibl>. </sense><sense n="II" id="n80557.14" level="2" opt="n"> <i>send in oneʼs own service</i> or <i>cause to be sent,</i> <bibl n="Perseus:abo:tlg,0011,004:556"><author>S.</author> <title>OT</title> 556</bibl>, <bibl n="Perseus:abo:tlg,0062,044:14" default="NO"><author>Luc.</author> <title>Tox.</title> 14</bibl>.`
	x := `<div2 id="crosspe/mpw" orig_id="n80557" key="pe/mpw" type="main" opt="n"><head extent="full" lang="greek" opt="n" orth_orig="πέμπω">πέμπω</head>, <gramGrp opt="n"><gram type="dialect" opt="n">Ep.</gram></gramGrp> <mood opt="n">inf.</mood> <foreign lang="greek">-έμεναι, -έμεν,</foreign> <bibl n="Perseus:abo:tlg,0012,002:13:48"><title>Od.</title> 13.48</bibl>, <bibl n="Perseus:abo:tlg,0012,002:10:18">10.18</bibl> : <gramGrp opt="n"><gram type="dialect" opt="n">Ion.</gram></gramGrp> <tns opt="n">impf.</tns> <cit><quote lang="greek">πέμπεσκε</quote> <bibl n="Perseus:abo:tlg,0016,001:7:106"><author>Hdt.</author> 7.106</bibl></cit> : <tns opt="n">fut.</tns> <cit><quote lang="greek">πέμψω</quote> <bibl n="Perseus:abo:tlg,0012,002:5:167"><title>Od.</title> 5.167</bibl></cit>, etc.; <gramGrp opt="n"><gram type="dialect" opt="n">Dor.</gram></gramGrp> <cit><quote lang="greek">πεμψῶ</quote> <bibl n="Perseus:abo:tlg,0005,001:5:141"><author>Theoc.</author> 5.141</bibl></cit>; <gramGrp opt="n"><gram type="dialect" opt="n">Ep.</gram></gramGrp> <mood opt="n">inf.</mood> <cit><quote lang="greek">πεμψέμεναι</quote> <bibl n="Perseus:abo:tlg,0012,002:10:484"><title>Od.</title> 10.484</bibl></cit>: <tns opt="n">aor.</tns> <foreign lang="greek">ἔπεμψα,</foreign> <gramGrp opt="n"><gram type="dialect" opt="n">Ep.</gram></gramGrp> <cit><quote lang="greek">πέμψα</quote> <bibl n="Perseus:abo:tlg,0012,001:1:442"><title>Il.</title> 1.442</bibl></cit>, <bibl n="Perseus:abo:tlg,0012,001:21:43">21.43</bibl>, etc.: <tns opt="n">pf.</tns> <cit><quote lang="greek">πέπομφα</quote> <bibl n="Perseus:abo:tlg,0003,001:7:12"><author>Th.</author> 7.12</bibl></cit>, <bibl n="Perseus:abo:tlg,0032,007:6:2:10"><author>X.</author> <title>Cyr.</title> 6.2.10</bibl>, <bibl n="Perseus:abo:tlg,0014,004:48"><author>D.</author> 4.48</bibl> : <tns opt="n">plpf.</tns> <foreign lang="greek">ἐπεμπόμφει,</foreign> <gramGrp opt="n"><gram type="dialect" opt="n">Ion.</gram></gramGrp> <foreign lang="greek">-εε,</foreign> <bibl n="Perseus:abo:tlg,0032,007:6:2:9"><author>X.</author> <title>Cyr.</title> 6.2.9</bibl>, <bibl n="Perseus:abo:tlg,0016,001:1:85"><author>Hdt.</author> 1.85</bibl> :—<gramGrp opt="n"><gram type="voice" opt="n">Med.</gram></gramGrp> (not in early Prose, exc. in compds. <foreign lang="greek">ἀπο-, μετα-, προ-πέμπομαι</foreign>), <tns opt="n">fut.</tns> <foreign lang="greek">πέμψομαι</foreign> only <abbr>f.l.</abbr> in <bibl n="Perseus:abo:tlg,0006,016:111"><author>E.</author> <title>Or.</title> 111</bibl> : <tns opt="n">aor.</tns> <cit><quote lang="greek">ἐπεμψάμην</quote> <bibl n="Perseus:abo:tlg,0006,007:977"><author>Id.</author> <title>Hec.</title> 977</bibl></cit> :—<gramGrp opt="n"><gram type="voice" opt="n">Pass.</gram></gramGrp>, <tns opt="n">fut.</tns> <cit><quote lang="greek">πεμφθήσομαι</quote> <bibl n="Perseus:abo:tlg,0099,001:1:1:4"><author>Str.</author> 1.1.4</bibl></cit>, <bibl n="Perseus:abo:tlg,0007,057:27" default="NO"><author>Plu.</author> <title>Demetr.</title> 27</bibl> : <tns opt="n">aor.</tns> <cit><quote lang="greek">ἐπέμφθην</quote> <bibl n="Perseus:abo:tlg,0033,003:3:59"><author>Pi.</author> <title>N.</title> 3.59</bibl></cit>, <bibl n="Perseus:abo:tlg,0011,005:1163"><author>S.</author> <title>El.</title> 1163</bibl>, etc.: <per opt="n">3</per> <number opt="n">sg.</number> <tns opt="n">pf.</tns> <cit><quote lang="greek">πέπεμπται</quote> <bibl n="Perseus:abo:tlg,0085,004:473"><author>A.</author> <title>Th.</title> 473</bibl></cit>, (<etym lang="greek" opt="n">προ-</etym>) <bibl n="Perseus:abo:tlg,0003,001:7:77"><author>Th.</author> 7.77</bibl>; <mood opt="n">part.</mood> <cit><quote lang="greek">πεπεμμένος</quote> <bibl n="Perseus:abo:tlg,0014,023:159"><author>D.</author> 23.159</bibl></cit>, <bibl n="Perseus:abo:tlg,0062,038:32" default="NO"><author>Luc.</author> <title>Alex.</title> 32</bibl>, <bibl n="Perseus:abo:tlg,0385,001:50:13" default="NO"><author>D.C.</author> 50.13</bibl>: <tns opt="n">plpf.</tns> <cit><quote lang="greek">ἐπέπεμπτο</quote> <bibl n="Perseus:abo:tlg,0385,001:36:18" default="NO"><author>Id.</author> 36.18</bibl></cit>, (<etym lang="greek" opt="n">προὐπ-</etym>) <bibl n="Perseus:abo:tlg,0003,001:8:79"><author>Th.</author> 8.79</bibl> (cj.) :—<sense id="n80557.0" n="" level="1" opt="n"><i>send,</i> freq. of persons, as messengers, spies, etc., <bibl n="Perseus:abo:tlg,0012,001:3:116"><title>Il.</title> 3.116</bibl>, <bibl n="Perseus:abo:tlg,0085,004:37"><author>A.</author> <title>Th.</title> 37</bibl>, <bibl n="Perseus:abo:tlg,0016,001:7:15"><author>Hdt.</author> 7.15</bibl>, etc.; of troops, <bibl n="Perseus:abo:tlg,0085,002:34"><author>A.</author> <title>Pers.</title> 34</bibl> (anap.), <bibl n="Perseus:abo:tlg,0085,004:470"><title>Th.</title> 470</bibl> : c. dupl. acc., <foreign lang="greek">ὁδὸν π. τινά</foreign> <i>send</i> one <i>on</i> a journey, <bibl n="Perseus:abo:tlg,0011,003:739"><author>S.</author> <title>Aj.</title> 739</bibl>, cf. <bibl n="Perseus:abo:tlg,0011,005:1163"><title>El.</title> 1163</bibl> (<gramGrp opt="n"><gram type="voice" opt="n">Pass.</gram></gramGrp>); also of things, <cit><quote lang="greek">πέμψω δέ τοι οὖρον ὄπισθεν</quote> <bibl n="Perseus:abo:tlg,0012,002:5:167"><title>Od.</title> 5.167</bibl></cit>, etc.; <foreign lang="greek">π. γράμματα, ἐπιστολήν,</foreign> <bibl n="Perseus:abo:tlg,0059,036:310d"><author>Pl.</author> <title>Ep.</title> 310d</bibl>, <bibl n="Perseus:abo:tlg,0059,036:323b">323b</bibl>; in letters, in the epistolary aorist, <bibl n="Perseus:abo:tlg,0003,001:1:129"><author>Th.</author> 1.129</bibl>, <bibl n="Perseus:abo:tlg,0032,006:1:9:25"><author>X.</author> <title>An.</title> 1.9.25</bibl>, <bibl n="Perseus:abo:tlg,0527,018:4:14"><author>LXX</author> <title>2 Es.</title> 4.14</bibl>; <foreign lang="greek">π. κακόν τινι</foreign> <i>send</i> one evil, <bibl n="Perseus:abo:tlg,0012,001:15:109"><title>Il.</title> 15.109</bibl>; <cit><quote lang="greek">π. παραβᾶσιν Ἐρινύν</quote> <bibl n="Perseus:abo:tlg,0085,005:59"><author>A.</author> <title>Ag.</title> 59</bibl></cit> (anap.); <foreign lang="greek">ποινάς, ζημίαν,</foreign> <bibl n="Perseus:abo:tlg,0085,007:203"><author>Id.</author> <title>Eu.</title> 203</bibl> (dub.), <bibl n="Perseus:abo:tlg,0006,020:506" default="NO"><author>E.</author> <title>Fr.</title> 506</bibl>; <cit><quote lang="greek">ψόφον π. ἔσω</quote> <bibl n="Perseus:abo:tlg,0006,013:1308"><author>Id.</author> <title>IT</title> 1308</bibl></cit>; <foreign lang="greek">ὕπνον, ὀνείρατα,</foreign> <bibl n="Perseus:abo:tlg,0011,006:19"><author>S.</author> <title>Ph.</title> 19</bibl>, <bibl n="Perseus:abo:tlg,0011,005:460"><title>El.</title> 460</bibl>; freq. of omens, <foreign lang="greek">π. οἰωνόν, τέρατα,</foreign> <bibl n="Perseus:abo:tlg,0012,001:24:310"><title>Il.</title> 24.310</bibl>, <bibl n="Perseus:abo:tlg,0032,002:1:4:15"><author>X.</author> <title>Mem.</title> 1.4.15</bibl>, cf. <bibl n="Perseus:abo:tlg,0032,004:4:48"><title>Smp.</title> 4.48</bibl>; <cit><quote lang="greek">μαντείας</quote> <bibl n="Perseus:abo:tlg,0011,004:149"><author>S.</author> <title>OT</title> 149</bibl></cit>; also <cit><quote lang="greek">ἱκεσίους π. λιτάς</quote> <bibl n="Perseus:abo:tlg,0011,006:495"><author>Id.</author> <title>Ph.</title> 495</bibl></cit> ; <foreign lang="greek">π. ἀρωγάς, ἀλκάν,</foreign> <bibl n="Perseus:abo:tlg,0085,007:598"><author>A.</author> <title>Eu.</title> 598</bibl>, <bibl n="Perseus:abo:tlg,0011,004:189"><author>S.</author> <title>OT</title> 189</bibl> (lyr.) :—Constr.: </sense><sense n="1" id="n80557.1" level="3" opt="n"> c. acc. of place to which, <foreign lang="greek">π. τινὰ Θήβας, ἀγρούς,</foreign> <bibl n="Perseus:abo:tlg,0011,007:1770"><author>Id.</author> <title>OC</title> 1770</bibl> (anap.), <bibl n="Perseus:abo:tlg,0011,004:761"><title>OT</title> 761</bibl> : also c. dat., <cit><quote lang="greek">Ἀΐδᾳ</quote> <bibl n="Perseus:abo:tlg,0006,013:159"><author>E.</author> <title>IT</title> 159</bibl></cit> (anap.): but usu. with Preps., <foreign lang="greek">ἐς Τροίην, φίλην ἐς πατρίδα γαῖαν,</foreign> etc., <bibl n="Perseus:abo:tlg,0012,001:6:207"><title>Il.</title> 6.207</bibl>, <bibl n="Perseus:abo:tlg,0012,002:5:37"><title>Od.</title> 5.37</bibl>, etc.; <cit><quote lang="greek">π. εἰς Ἀΐδαο</quote> <bibl n="Perseus:abo:tlg,0012,001:21:48"><title>Il.</title> 21.48</bibl></cit> ; <cit><quote lang="greek">δόμον Ἄϊδος εἴσω</quote> <bibl n="Perseus:abo:tlg,0012,002:9:524"><title>Od.</title> 9.524</bibl></cit>; <foreign lang="greek">π. εἰς διδασκάλων</foreign> <i>send</i> to school, <bibl n="Perseus:abo:tlg,0059,022:325d"><author>Pl.</author> <title>Prt.</title> 325d</bibl> (so <foreign lang="greek">πέμπειν</foreign> alone, <bibl n="Perseus:abo:tlg,0019,012:216" default="NO"><author>Ar.</author> <title>Fr.</title> 216</bibl>); <foreign lang="greek">π. ἐπʼ εὐρέα νῶτα θαλάσσης</foreign> <i>over. . ,</i> <bibl n="Perseus:abo:tlg,0012,002:4:560"><title>Od.</title> 4.560</bibl>, etc. ; <foreign lang="greek">π.ἐπὶ Θρῃκῶν ἵππους</foreign> <i>to</i> them, <bibl n="Perseus:abo:tlg,0012,001:10:464"><title>Il.</title> 10.464</bibl>; but <foreign lang="greek">πέμπειν ἐπί τι</foreign> <i>send for</i> a purpose, <cit><quote lang="greek">ἐπʼ ὕδωρ</quote> <bibl n="Perseus:abo:tlg,0016,001:5:12"><author>Hdt.</author> 5.12</bibl></cit> ; <cit><quote lang="greek">ἐπὶ κατασκοπήν</quote> <bibl n="Perseus:abo:tlg,0032,007:6:2:9"><author>X.</author> <title>Cyr.</title> 6.2.9</bibl></cit> (<foreign lang="greek">π. εἰς κ</foreign>. <bibl n="Perseus:abo:tlg,0011,006:45"><author>S.</author> <title>Ph.</title> 45</bibl>); <cit><quote lang="greek">π. ἀρωγὴν ἐπὶ νίκην</quote> <bibl n="Perseus:abo:tlg,0085,006:477"><author>A.</author> <title>Ch.</title> 477</bibl></cit> codd. (anap.); <foreign lang="greek">π. ἐπί τινι</foreign> <i>send to</i> him, <bibl n="Perseus:abo:tlg,0012,001:2:6"><title>Il.</title> 2.6</bibl>; <i>against. . ,</i> <bibl n="Perseus:abo:tlg,0085,005:61"><author>A.</author> <title>Ag.</title> 61</bibl> (anap.), etc.; <i>for</i> a purpose, <cit><quote lang="greek">ἐπὶ πολέμῳ</quote> <bibl n="Perseus:abo:tlg,0032,001:4:8:17"><author>X.</author> <title>HG</title> 4.8.17</bibl></cit>; <foreign lang="greek">περί τινος</foreign> about something, <bibl n="Perseus:abo:tlg,0003,001:1:91"><author>Th.</author> 1.91</bibl>, <bibl n="Perseus:abo:tlg,0032,007:6:2:10"><author>X.</author> <title>Cyr.</title> 6.2.10</bibl>; <foreign lang="greek">ὑπέρ τινος</foreign> Epist. Philipp. ap. <bibl n="Perseus:abo:tlg,0014,012:12"><author>D.</author> 12.12</bibl>; <foreign lang="greek">παρά</foreign> or <foreign lang="greek">πρός τινα</foreign> <i>to</i> some one, <bibl n="Perseus:abo:tlg,0003,001:2:81"><author>Th.</author> 2.81</bibl>, <bibl n="Perseus:abo:tlg,0032,006:5:2:6"><author>X.</author> <title>An.</title> 5.2.6</bibl>; <cit><quote lang="greek">ὥς τινα</quote> <bibl n="Perseus:abo:tlg,0003,001:8:50"><author>Th.</author> 8.50</bibl></cit>. </sense><sense n="2" id="n80557.2" level="3" opt="n"> folld. by Advbs., <foreign lang="greek">οἴκαδε, οἶκόνδε,</foreign> <bibl n="Perseus:abo:tlg,0012,002:19:281"><title>Od.</title> 19.281</bibl>, <bibl n="Perseus:abo:tlg,0012,002:24:418">24.418</bibl>; <cit><quote lang="greek">ὅνδε δόμονδε</quote> <bibl n="Perseus:abo:tlg,0012,001:16:445"><title>Il.</title> 16.445</bibl></cit>; <cit><quote lang="greek">θύραζε</quote> <bibl n="Perseus:abo:tlg,0012,002:9:461"><title>Od.</title> 9.461</bibl></cit>; <cit><quote lang="greek">πόλεμόνδε</quote> <bibl n="Perseus:abo:tlg,0012,001:18:452"><title>Il.</title> 18.452</bibl></cit>, etc.; <foreign lang="greek">ἕταρον γὰρ . . πέμπʼ Ἄϊδόσδε</foreign> <i>was conducting</i> or <i>convoying</i> Patroclus to Hades, <bibl n="Perseus:abo:tlg,0012,001:23:137">23.137</bibl>. </sense><sense n="3" id="n80557.3" level="3" opt="n"> folld. by <mood opt="n">inf.</mood> of purpose, <cit><quote lang="greek">τὴν . . ἅρμασι π. νέεσθαι</quote> <bibl n="Perseus:abo:tlg,0012,002:4:8"><title>Od.</title> 4.8</bibl></cit> ; <cit><quote lang="greek">ἕπεσθαι</quote> <bibl n="Perseus:abo:tlg,0012,001:16:575"><title>Il.</title> 16.575</bibl></cit> ; <cit><quote lang="greek">ἰέναι</quote> <bibl n="Perseus:abo:tlg,0012,002:14:396"><title>Od.</title> 14.396</bibl></cit> ; <cit><quote lang="greek">ἱκανέμεν</quote> <bibl n="Perseus:abo:tlg,0012,002:4:29">4.29</bibl></cit> ; <cit><quote lang="greek">ἄγειν</quote> <bibl n="Perseus:abo:tlg,0012,002:24:419">24.419</bibl></cit>; <cit><quote lang="greek">φέρειν</quote> <bibl n="Perseus:abo:tlg,0012,001:16:454"><title>Il.</title> 16.454</bibl></cit> ; <foreign lang="greek">φέρεσθαι</foreign> ib. <bibl n="Perseus:abo:tlg,0012,001:16:681">681</bibl> ; <cit><quote lang="greek">μήτηρ με πέμπει πατρὶ τυμβεῦσαι χοάς</quote> <bibl n="Perseus:abo:tlg,0011,005:406"><author>S.</author> <title>El.</title> 406</bibl></cit> ; <i>send word,</i> <cit><quote lang="greek">πέμπεις . . σῇ δάμαρτι, παῖδα σὴν δεῦρʼ ἀποστέλλειν</quote> <bibl n="Perseus:abo:tlg,0006,018:360"><author>E.</author> <title>IA</title> 360</bibl></cit> ; <foreign lang="greek">πέμπουσιν οἱ ἔφοροι . . στρατεύεσθαι</foreign> <i>sent him orders</i> to march, <bibl n="Perseus:abo:tlg,0032,001:3:1:7"><author>X.</author> <title>HG</title> 3.1.7</bibl> : also c. <mood opt="n">part.</mood>, <cit><quote lang="greek">κήρυκας π. ἀγγέλλοντας</quote> <title>IG</title> 1(2).76.22</cit> : the place from which is expressed by <foreign lang="greek">ἀπό</foreign> or <foreign lang="greek">ἐκ,</foreign> <bibl n="Perseus:abo:tlg,0012,001:16:447"><title>Il.</title> 16.447</bibl>, <bibl n="Perseus:abo:tlg,0012,002:11:635"><title>Od.</title> 11.635</bibl>, etc. </sense><sense n="4" id="n80557.4" level="3" opt="n"> abs., <cit><quote lang="greek">ἐπέμψαμεν πρὸς ὑμᾶς περὶ ἀποστάσεως</quote> <bibl n="Perseus:abo:tlg,0003,001:3:13"><author>Th.</author> 3.13</bibl></cit> ; <cit><quote lang="greek">πέμπει κελεύων</quote> <bibl n="Perseus:abo:tlg,0003,001:1:91"><author>Th.</author> 1.91</bibl></cit>, <bibl n="Perseus:abo:tlg,0003,001:2:81">2.81</bibl>; <cit><quote lang="greek">ἐκέλευε . . πέμπων</quote> <bibl n="Perseus:abo:tlg,0032,006:2:3:1"><author>X.</author> <title>An.</title> 2.3.1</bibl></cit> ; <cit><quote lang="greek">ἔπεμπε πρὸς Κῦρον δεόμενος</quote> <bibl n="Perseus:abo:tlg,0032,007:1:5:4"><author>Id.</author> <title>Cyr.</title> 1.5.4</bibl></cit> ; <cit><quote lang="greek">ἔπεμπον ἐρωτῶντες</quote> <bibl n="Perseus:abo:tlg,0032,006:6:6:4"><author>Id.</author> <title>An.</title> 6.6.4</bibl></cit>, etc. </sense><sense n="5" id="n80557.5" level="3" opt="n"> <i>send forward, nominate</i> a person for a post, <foreign lang="greek">ὀνόματα</foreign> Wilcken <title>Chr.</title> 28.20 <date>(ii A.D.)</date> :—<gramGrp opt="n"><gram type="voice" opt="n">Pass.</gram></gramGrp>, ib. 392.7 <date>(ii A.D.)</date>. </sense><sense n="II" id="n80557.6" level="2" opt="n"> <i>send forth</i> or <i>away, dismiss, send home,</i> <cit><quote lang="greek">τὸν ξεῖνον</quote> <bibl n="Perseus:abo:tlg,0012,002:7:227"><title>Od.</title> 7.227</bibl></cit>, al.: less freq. in <title>Il.</title>, as <bibl n="Perseus:abo:tlg,0012,001:24:780">24.780</bibl>; <foreign lang="greek">χρὴ ξεῖνον παρεόντα φιλεῖν, ἐθέλοντα δὲ πέμπειν</foreign> ‘welcome the coming, <i>speed</i> the parting guest’, <bibl n="Perseus:abo:tlg,0012,002:15:74"><title>Od.</title> 15.74</bibl> ; <cit><quote lang="greek">ὑπέδεκτο καὶ πέμπε</quote> <bibl n="Perseus:abo:tlg,0012,002:23:315">23.315</bibl></cit> ; of the father who sends off his daughter to go to her husband, c. dat., <bibl n="Perseus:abo:tlg,0012,002:4:5">4.5</bibl> ; <cit><quote lang="greek">π. τινὰ ἄποικον</quote> <bibl n="Perseus:abo:tlg,0011,004:1518"><author>S.</author> <title>OT</title> 1518</bibl></cit>, etc. </sense><sense n="2" id="n80557.7" level="3" opt="n"> of missiles, <i>discharge, shoot,</i> <cit><quote lang="greek">πέτρας</quote> <bibl n="Perseus:abo:tlg,0020,001:716"><author>Hes.</author> <title>Th.</title> 716</bibl></cit> : metaph., <cit><quote lang="greek">ὄμματος . . τόξευμα</quote> <bibl n="Perseus:abo:tlg,0085,001:1005"><author>A.</author> <title>Supp.</title> 1005</bibl></cit> : abs., <cit><quote lang="greek">οἱ πολλάκις πέμποντες ἔστιν ὅτε τυγχάνουσι τοῦ σκοποῦ</quote> <bibl n="Perseus:abo:tlg,2050,001:p.495" default="NO"><author>Eun.</author> <title>VS</title> p.495</bibl></cit> B. </sense><sense n="3" id="n80557.8" level="3" opt="n"> of words, <i>send forth, utter,</i> <bibl n="Perseus:abo:tlg,0085,004:443"><author>A.</author> <title>Th.</title> 443</bibl>, <bibl n="Perseus:abo:tlg,0011,006:846"><author>S.</author> <title>Ph.</title> 846</bibl> (lyr.), <bibl n="Perseus:abo:tlg,0011,006:1445">1445</bibl> (anap.). </sense><sense n="III" id="n80557.9" level="2" opt="n"> <i>conduct, escort,</i> <bibl n="Perseus:abo:tlg,0012,001:1:390"><title>Il.</title> 1.390</bibl>, <bibl n="Perseus:abo:tlg,0012,002:14:336"><title>Od.</title> 14.336</bibl>, <bibl n="Perseus:abo:tlg,0011,001:571"><author>S.</author> <title>Tr.</title> 571</bibl>, etc.; freq. of Hermes and other gods, <bibl n="Perseus:abo:tlg,0012,002:11:626"><title>Od.</title> 11.626</bibl>, <bibl n="Perseus:abo:tlg,0085,007:12"><author>A.</author> <title>Eu.</title> 12</bibl>, <bibl n="Perseus:abo:tlg,0085,001:219"><title>Supp.</title> 219</bibl>; <foreign lang="greek">ὁ πέμπων</foreign> abs., of Hermes, <bibl n="Perseus:abo:tlg,0011,006:133"><author>S.</author> <title>Ph.</title> 133</bibl> (cf. <foreign lang="greek">πομπός, πομπαῖος,</foreign> etc.); of a ship, <i>convey, carry,</i> <bibl n="Perseus:abo:tlg,0012,002:8:556"><title>Od.</title> 8.556</bibl>, cf. <bibl n="Perseus:abo:tlg,0085,001:136"><author>A.</author> <title>Supp.</title> 136</bibl> (lyr.); <cit><quote lang="greek">κραιπνοφόροι δέ μʼ ἔπεμψαν αὖραι</quote> <bibl n="Perseus:abo:tlg,0085,003:132"><author>Id.</author> <title>Pr.</title> 132</bibl></cit> (lyr.), cf. <bibl n="Perseus:abo:tlg,0033,002:4:203"><author>Pi.</author> <title>P.</title> 4.203</bibl> (<gramGrp opt="n"><gram type="voice" opt="n">Pass.</gram></gramGrp>). </sense><sense n="2" id="n80557.10" level="3" opt="n"> <foreign lang="greek">πομπὴν π</foreign>. <i>conduct,</i> or <i>take part in,</i> a procession, <bibl n="Perseus:abo:tlg,0016,001:5:56"><author>Hdt.</author> 5.56</bibl>, <bibl n="Perseus:abo:tlg,0019,010:757"><author>Ar.</author> <title>Ec.</title> 757</bibl>, <bibl n="Perseus:abo:tlg,0003,001:6:56"><author>Th.</author> 6.56</bibl>, <bibl n="Perseus:abo:tlg,0540,013:80"><author>Lys.</author> 13.80</bibl>, <bibl n="Perseus:abo:tlg,0014,004:26"><author>D.</author> 4.26</bibl>, etc.; <foreign lang="greek">π. χορούς</foreign> <i>move in</i> dancing <i>procession,</i> <bibl n="Perseus:abo:tlg,0006,012:434"><author>E.</author> <title>El.</title> 434</bibl> (lyr.); <foreign lang="greek">Παναθήναια π</foreign>. <bibl n="Perseus:abo:tlg,0541,001:494" default="NO"><author>Men.</author> 494</bibl>, <bibl n="Perseus:abo:tlg,0638,001:4:22" default="NO"><author>Philostr.</author> <title>VA</title> 4.22</bibl> :—<gramGrp opt="n"><gram type="voice" opt="n">Pass.</gram></gramGrp>, <foreign lang="greek">φαλλὸς Διονύσῳ πεμπόμενος</foreign> <i>carried in procession</i> in his honour, <bibl n="Perseus:abo:tlg,0016,001:2:49"><author>Hdt.</author> 2.49</bibl>, cf. <bibl n="Perseus:abo:tlg,0007,019:32" default="NO"><author>Plu.</author> <title>Aem.</title> 32</bibl>, <bibl n="Perseus:abo:tlg,0007,057:12" default="NO"><title>Demetr.</title> 12</bibl>; <cit><quote lang="greek">τῆς πομπῆς ὅπως ἂν ὡς κάλλισταπεμφθῇ</quote> <title>IG</title> 1(2).84.27</cit>; <cit><quote lang="greek">χορὸς ὁ εἰς Δῆλον πεμπόμενος</quote> <bibl n="Perseus:abo:tlg,0032,002:3:3:12"><author>X.</author> <title>Mem.</title> 3.3.12</bibl></cit>. </sense><sense n="IV" id="n80557.11" level="2" opt="n"> <i>send</i> as a present, <foreign lang="greek">εἵματα, σῖτον,</foreign> <bibl n="Perseus:abo:tlg,0012,002:16:83"><title>Od.</title> 16.83</bibl>, <bibl n="Perseus:abo:tlg,0012,002:4:623">4.623</bibl>; <foreign lang="greek">π. δῶρα, σκῦλα, ξένια,</foreign> <bibl n="Perseus:abo:tlg,0016,001:7:106"><author>Hdt.</author> 7.106</bibl> (<gramGrp opt="n"><gram type="voice" opt="n">Act.</gram></gramGrp> and <gramGrp opt="n"><gram type="voice" opt="n">Pass.</gram></gramGrp>), <bibl n="Perseus:abo:tlg,0011,006:1429"><author>S.</author> <title>Ph.</title> 1429</bibl>, <bibl n="Perseus:abo:tlg,0032,007:3:1:42"><author>X.</author> <title>Cyr.</title> 3.1.42</bibl>. </sense><sense n="V" id="n80557.12" level="2" opt="n"> <i>send up, produce,</i> <cit><quote lang="greek">ὅσα πέμπει βιόδωρος αἶα</quote> <bibl n="Perseus:abo:tlg,0011,006:1162"><author>S.</author> <title>Ph.</title> 1162</bibl></cit> (lyr.). </sense><sense n="B" id="n80557.13" level="1" opt="n"> <gramGrp opt="n"><gram type="voice" opt="n">Med.</gram></gramGrp>, <foreign lang="greek">πέμπεσθαί τινα</foreign> <i>send for</i> one, <bibl n="Perseus:abo:tlg,0011,007:602"><author>S.</author> <title>OC</title> 602</bibl>, ubiv. Sch.; <foreign lang="greek">τί χρῆμʼ ἐπέμψω τὸν ἐμὸν ἐκ δόμων πόδα</foreign>; <bibl n="Perseus:abo:tlg,0006,007:977"><author>E.</author> <title>Hec.</title> 977</bibl>. </sense><sense n="II" id="n80557.14" level="2" opt="n"> <i>send in oneʼs own service</i> or <i>cause to be sent,</i> <bibl n="Perseus:abo:tlg,0011,004:556"><author>S.</author> <title>OT</title> 556</bibl>, <bibl n="Perseus:abo:tlg,0062,044:14" default="NO"><author>Luc.</author> <title>Tox.</title> 14</bibl>.</sense></div2>`
	y, _ := FindGreekLexEntries(x)
	fmt.Println(y)
}

func TestFixBlankBibl(t *testing.T) {
	x := `<bibl id="perseus/lt0845/002/8:11:8"><hb-lx-au>Columella</hb-lx-au> 8, 11, 8</bibl></cit>; <bibl><hb-lx-au>Palladius</hb-lx-au> 1, 28, 2</bibl> (see also gemma, II. 2. c. and gemmeus, II. B.): <cit><hb-lx-lt-quote>memphites (lapis) gemmantis naturae,</hb-lx-lt-quote> <bibl id="perseus/lt0978/001/36:56" valid="yes"><hb-lx-au>Pliny</hb-lx-au> 36, 7, 11, § 56</bibl></cit>.`
	y := fixblankbibl(x)
	fmt.Println(y)
}

func TestFixVarro(t *testing.T) {
	x := `"Perseus:abo:phi,0684,001:L. L. 5:section=59"`
	y := fixvarro(x)
	z := `"Perseus:abo:phi,0684,001:5:59"`
	fmt.Println(y)
	if y != z {
		t.Errorf("fixvarro(%q)\ngot\n%q\nwant\n%q", x, y, z)
	}
}

func TestFixibidem(t *testing.T) {
	x := `"Perseus:abo:phi,1014,001:ib. 76:2"`
	y := fixibidem(x)
	z := `"Perseus:abo:phi,1014,001:76:2"`
	fmt.Println(y)
	if y != z {
		t.Errorf("fixibidem(%q)\ngot\n%q\nwant\n%q", x, y, z)
	}
}

func TestFixBaccyl(t *testing.T) {
	x := `<quote lang="greek">κέρδεσσι</quote> <bibl n="Perseus:abo:tlg,0199,001:14:57"><author>B.</author> 14.57</bibl> xx <bibl n="Perseus:abo:tlg,0011,006:1000"><title>Ph.</title> 1000</bibl>; <cit>`
	y := fixbacchylides(x)
	fmt.Println(y)
}

